def _validate_payload(data):
    """Raise ``TypeError`` when a request payload is malformed."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not all(isinstance(key, str) for key in data.keys()):
        raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Process an incoming API request payload.

    Args:
        data: The request payload. Outside legacy mode, this must be a
            dictionary whose keys are strings.
        legacy_mode: If true, skip payload validation for older clients.

    Raises:
        TypeError: If validation is enabled and ``data`` is not a dictionary,
            or if any of its keys are not strings.
    """
    if not legacy_mode:
        _validate_payload(data)

    return process(data)

